    // Prevent overflowing size_t\n        if (capacity_ > SIZE_MAX - 2 * kPadding) {\n            capacity_ = SIZE_MAX - 2 * kPadding;\n        }\n\n        // Allocate memory buffer\n        slots_ = std::allocator_traits<Allocator>::allocate(\n            allocator_, capacity_ + 2 * kPadding);\n\n        static_assert(alignof(SPSCQueue<T>) == kCacheLineSize, "");\n        static_assert(sizeof(SPSCQueue<T>) >= 3 * kCacheLineSize, "");\n\n        assert(reinterpret_cast<char*>(&readIdx_) - reinterpret_cast<char*>(&writeIdx_) >=\n            static_cast<std::ptrdiff_t>(kCacheLineSize));\n    }\n\n    ~SPSCQueue() \n    {\n        while (front()) pop();\n\n        // Free memory\n        std::allocator_traits<Allocator>::deallocate(\n            allocator_, slots_, \n            capacity_ + 2 * kPadding);\n    }\n\n    // non-copyable and non-movable\n    SPSCQueue(const SPSCQueue &) = delete;\n    SPSCQueue &operator=(const SPSCQueue &) = delete;\n\n    template <typename... Args>\n    void emplace(Args &&...args) noexcept(std::is_nothrow_constructible<T, Args &&...>::value) \n    {\n        static_assert(std::is_constructible<T, Args &&...>::value,\n                      "T must be constructible with Args&&...");\n\n        auto const writeIdx = writeIdx_.load(std::memory_order_relaxed);\n        auto nextWriteIdx = writeIdx + 1;\n\n        if (nextWriteIdx == capacity_) {\n            nextWriteIdx = 0;\n        }\n\n        while (nextWriteIdx == readIdxCache_) {\n            readIdxCache_ = readIdx_.load(std::memory_order_acquire);\n        }\n\n        new (&slots_[writeIdx + kPadding]) T(std::forward<Args>(args)...);\n        writeIdx_.store(nextWriteIdx, std::memory_order_release);\n    }\n\n    template <typename... Args>\n    bool try_emplace(Args &&...args) noexcept(\n        std::is_nothrow_constructible<T, Args &&...>::value) \n    {\n        static_assert(std::is_constructible<T, Args &&...>::value,\n                      "T must be constructible with Args&&...");\n\n        auto const writeIdx = writeIdx_.load(std::memory_order_relaxed);\n        auto nextWriteIdx = writeIdx + 1;\n\n        if (nextWriteIdx == capacity_) {\n            nextWriteIdx = 0;\n        }\n\n        if (nextWriteIdx == readIdxCache_) {\n            readIdxCache_ = readIdx_.load(std::memory_order_acquire);\n            if (nextWriteIdx == readIdxCache_) {\n                return false;\n            }\n        }\n\n        new (&slots_[writeIdx + kPadding]) T(std::forward<Args>(args)...);\n        writeIdx_.store(nextWriteIdx, std::memory_order_release);\n        return true;\n    }\n\n    void push(const T &v) noexcept(std::is_nothrow_copy_constructible<T>::value) \n    {\n        static_assert(std::is_copy_constructible<T>::value,\n                      "T must be copy constructible");\n        \n        emplace(v);\n    }\n\n    template <typename P, typename = typename std::enable_if<\n        std::is_constructible<T, P &&>::value>::type>\n    void push(P &&v) noexcept(std::is_nothrow_constructible<T, P &&>::value) \n    {\n        emplace(std::forward<P>(v));\n    }\n\n    bool try_push(const T &v) noexcept(std::is_nothrow_copy_constructible<T>::value) \n    {\n        static_assert(std::is_copy_constructible<T>::value,\n                    "T must be copy constructible");\n\n        return try_emplace(v);\n    }\n\n    template <typename P, typename = typename std::enable_if<\n        std::is_constructible<T, P &&>::value>::type>\n    bool try_push(P &&v) noexcept(std::is_nothrow_constructible<T, P &&>::value) \n    {\n        return try_emplace(std::forward<P>(v));\n    }\n\n    T *front() noexcept \n    {\n        auto const readIdx = readIdx_.load(std::memory_order_relaxed);\n\n        if (readIdx == writeIdxCache_) {\n            writeIdxCache_ = writeIdx_.load(std::memory_order_acquire);\n\n            if (writeIdxCache_ == readIdx) {\n                return nullptr;\n            }\n        }\n        return &slots_[readIdx + kPadding];\n    }\n\n    void pop() noexcept \n    {\n        static_assert(std::is_nothrow_destructible<T>::value,\n                    "T must be nothrow destructible");\n\n        auto const readIdx = readIdx_.load(std::memory_order_relaxed);\n\n        assert(writeIdx_.load(std::memory_order_acquire) != readIdx &&\n            "Can only call pop() after front() has returned a non-nullptr");\n\n        slots_[readIdx + kPadding].~T();\n        auto nextReadIdx = readIdx + 1;\n\n        if (nextReadIdx == capacity_) {\n            nextReadIdx = 0;\n        }\n        readIdx_.store(nextReadIdx, std::memory_order_release);\n    }\n\n    size_t size() const noexcept \n    {\n        std::ptrdiff_t diff = writeIdx_.load(std::memory_order_acquire) -\n            readIdx_.load(std::memory_order_acquire);\n\n        if (diff < 0) {\n            diff += capacity_;\n        }\n        return static_cast<size_t>(diff);\n    }\n\n    bool empty() const noexcept \n    {\n        return writeIdx_.load(std::memory_order_acquire) ==\n            readIdx_.load(std::memory_order_acquire);\n    }\n\n    size_t capacity() const noexcept { return capacity_ - 1; }\n\nprivate:\n\n#ifdef __cpp_lib_hardware_interference_size\n    static constexpr size_t kCacheLineSize = std::hardware_destructive_interference_size;\n#else\n    static constexpr size_t kCacheLineSize = 64;\n#endif\n\n    // Padding to avoid false sharing between slots_ and adjacent allocations\n    static constexpr size_t kPadding = (kCacheLineSize - 1) / sizeof(T) + 1;\n\n    size_t capacity_;\n    T *slots_;\n    \n    #if defined(__has_cpp_attribute) && __has_cpp_attribute(no_unique_address)\n        Allocator allocator_ [[no_unique_address]];\n    #else\n        Allocator allocator_;\n    #endif\n\n    // Align to cache line size in order to avoid false sharing\n    // readIdxCache_ and writeIdxCache_ is used to reduce the amount of cache\n    // coherency traffic\n    alignas(kCacheLineSize) std::atomic<size_t> writeIdx_